/* HCF 品牌金牌 3D 勳章 — 可重用、無邊框懸浮展示
 * 用法：<canvas id="x"></canvas> + HCFMedal.mount(document.getElementById('x'), {spin:0.006, draggable:true});
 * 需先載入 THREE r128（UMD）。canvas 透明背景，可放任何深色區塊自由懸浮。*/
(function(){
  var GOLD="data:image/png;base64,";
  var LOGO="data:image/png;base64,";
  function lit(hex,f){var n=parseInt(hex.slice(1),16),r=(n>>16)+f,g=((n>>8)&255)+f,b=(n&255)+f;return 'rgb('+Math.max(0,Math.min(255,r))+','+Math.max(0,Math.min(255,g))+','+Math.max(0,Math.min(255,b))+')';}
  function envTex(THREE){var c=document.createElement('canvas');c.width=1024;c.height=512;var x=c.getContext('2d');var g=x.createLinearGradient(0,0,0,512);g.addColorStop(0,'#05060a');g.addColorStop(0.4,'#333941');g.addColorStop(0.49,'#eef2f6');g.addColorStop(0.58,'#333941');g.addColorStop(1,'#05060a');x.fillStyle=g;x.fillRect(0,0,1024,512);x.globalCompositeOperation='lighter';function bl(cx,cy,r,col){var rg=x.createRadialGradient(cx,cy,0,cx,cy,r);rg.addColorStop(0,col);rg.addColorStop(1,'rgba(0,0,0,0)');x.fillStyle=rg;x.beginPath();x.arc(cx,cy,r,0,7);x.fill();}bl(250,170,190,'rgba(255,190,130,.55)');bl(800,300,160,'rgba(150,180,255,.4)');bl(560,120,120,'rgba(255,255,255,.5)');var t=new THREE.CanvasTexture(c);t.mapping=THREE.EquirectangularReflectionMapping;return t;}
  function faceTex(THREE,gimg){var s=1024,c=document.createElement('canvas');c.width=c.height=s;var x=c.getContext('2d');var g=x.createRadialGradient(s*0.4,s*0.34,60,s*0.5,s*0.5,s*0.62);g.addColorStop(0,lit('#8a5f16',150));g.addColorStop(0.55,lit('#8a5f16',80));g.addColorStop(1,lit('#8a5f16',12));x.fillStyle=g;x.beginPath();x.arc(s/2,s/2,s/2,0,7);x.fill();x.strokeStyle='rgba(0,0,0,.18)';x.lineWidth=6;x.beginPath();x.arc(s/2,s/2,s*0.455,0,7);x.stroke();if(gimg)x.drawImage(gimg,s*0.12,s*0.12,s*0.76,s*0.76);var t=new THREE.CanvasTexture(c);t.anisotropy=8;t.encoding=THREE.sRGBEncoding;return t;}
  function mount(canvas,opts){
    opts=opts||{};var THREE=window.THREE;if(!canvas||!THREE)return;
    if(canvas.__hcfMedal)return;canvas.__hcfMedal=true;
    var SPIN=opts.spin!=null?opts.spin:0.006, DRAG=opts.draggable!==false;
    var gimg=null,limg=null,n=0;
    function ready(){if(++n>=2){try{build();}catch(e){console.error(e);}}}
    var a=new Image();a.onload=function(){gimg=a;ready();};a.onerror=ready;a.src=GOLD;
    var b=new Image();b.onload=function(){limg=b;ready();};b.onerror=ready;b.src=LOGO;
    function build(){
      var r=new THREE.WebGLRenderer({canvas:canvas,alpha:true,antialias:true});
      r.setPixelRatio(Math.min(window.devicePixelRatio||1,2));
      var w=canvas.clientWidth||canvas.width||300,h=canvas.clientHeight||canvas.height||300;
      r.setSize(w,h,false);r.outputEncoding=THREE.sRGBEncoding;r.toneMapping=THREE.ACESFilmicToneMapping;r.toneMappingExposure=1.2;
      var s=new THREE.Scene();var cam=new THREE.PerspectiveCamera(34,w/h,0.1,100);cam.position.set(0,0,7.4);
      var pm=new THREE.PMREMGenerator(r);s.environment=pm.fromEquirectangular(envTex(THREE)).texture;
      s.add(new THREE.AmbientLight(0xffffff,0.12));var k=new THREE.DirectionalLight(0xffffff,1.2);k.position.set(-3,4,6);s.add(k);
      var coin=new THREE.Group();s.add(coin);
      var R=2,TH=0.24,face=faceTex(THREE,gimg);
      var edge=new THREE.MeshPhysicalMaterial({color:new THREE.Color('#8a5f16'),metalness:1,roughness:0.24,envMapIntensity:1.7});
      coin.add(new THREE.Mesh(new THREE.CylinderGeometry(R,R,TH,120,1,false).rotateX(Math.PI/2),edge));
      var fg=new THREE.CircleGeometry(R*0.985,120);
      var fm=new THREE.MeshPhysicalMaterial({map:face,bumpMap:face,bumpScale:0.07,metalness:1,roughness:0.24,envMapIntensity:1.7});
      var fd=new THREE.Mesh(fg,fm);fd.position.z=TH/2+0.002;coin.add(fd);
      var bd=new THREE.Mesh(fg,fm.clone());bd.position.z=-(TH/2+0.002);bd.rotation.y=Math.PI;coin.add(bd);
      for(var i=0;i<90;i++){var an=i/90*Math.PI*2;var bx=new THREE.Mesh(new THREE.BoxGeometry(0.05,TH*0.9,0.11),edge);bx.position.set(Math.cos(an)*R,Math.sin(an)*R,0);bx.rotation.z=an;coin.add(bx);}
      var rm=new THREE.MeshPhysicalMaterial({color:new THREE.Color('#e9c64b'),metalness:1,roughness:0.22,envMapIntensity:1.8});
      var rg2=new THREE.Mesh(new THREE.TorusGeometry(0.32,0.085,20,44),rm);rg2.position.set(0,R+0.26,0);coin.add(rg2);
      var bar=new THREE.Mesh(new THREE.CylinderGeometry(0.06,0.06,0.34,20),rm);bar.position.set(0,R+0.02,0);coin.add(bar);
      var drag=false,lx=0,ly=0,vx=0,vy=0,tX=0,tY=0;
      if(DRAG){
        canvas.style.touchAction='none';
        canvas.addEventListener('pointerdown',function(e){drag=true;lx=e.clientX;ly=e.clientY;vx=vy=0;try{canvas.setPointerCapture(e.pointerId);}catch(_){}}); 
        canvas.addEventListener('pointermove',function(e){if(!drag)return;var dx=e.clientX-lx,dy=e.clientY-ly;lx=e.clientX;ly=e.clientY;tY+=dx*0.01;tX+=dy*0.01;vx=dx*0.01;vy=dy*0.01;});
        canvas.addEventListener('pointerup',function(){drag=false;});canvas.addEventListener('pointercancel',function(){drag=false;});
      }
      function resize(){var ww=canvas.clientWidth,hh=canvas.clientHeight;if(!ww||!hh)return;cam.aspect=ww/hh;cam.updateProjectionMatrix();r.setSize(ww,hh,false);}
      window.addEventListener('resize',resize);
      (function loop(){requestAnimationFrame(loop);if(!drag){tY+=SPIN;tY+=vx;tX+=vy;vx*=0.94;vy*=0.94;}tX*=1;coin.rotation.y+=(tY-coin.rotation.y)*0.12;coin.rotation.x+=(Math.max(-0.6,Math.min(0.6,tX))-coin.rotation.x)*0.12;r.render(s,cam);})();
    }
  }
  window.HCFMedal={mount:mount};
})();
